const {mat} = NMath;
const samples = await IO.loadMNIST();
const D = samples[0].length; // 784 for MNIST
const N = samples.length;

// 1. Convert samples into a data matrix of shape [D, N] (Rows = features, Cols = samples)
const X = mat.ofVectors(samples);

// 2. Choose an intermediate dimension (e.g., m = 50) for Random Projection
const m = 50; 

// 3. Create a random projection matrix of shape [m, D]
// Scaled by 1 / sqrt(m) to preserve vector lengths and distances (Gaussian Random Projection)
const rawR = mat.random(m, D, {distribution: "gaussian"});
const scale = 1 / Math.sqrt(m);
const R = rawR.scale(scale);

// 4. Project the data matrix: Y = R * X (resulting shape: [m, N])
const Y = R.prod(X);

// 5. Extract the columns of Y back into an array of sample vectors (shape: [N, m])
const intermediateSamples = [];
for (let j = 0; j < N; j++) {
  const sampleVec = [];
  for (let i = 0; i < m; i++) {
    sampleVec.push(Y.get(i, j));
  }
  intermediateSamples.push(sampleVec);
}

// 6. Apply standard PCA on the intermediate representation down to 3 dimensions
const k = 3;
const pca = PCA.new(intermediateSamples, k);

// 7. Project the intermediate samples using PCA and visualize
const pcaCoords = intermediateSamples.map(sample => pca.proj(sample));
IO.projectMNIST(samples, pcaCoords);
